From curiosity, in the case of monkeypatching.
This is 10% faster than the nonenumerable version.

``` diff
diff --git a/lib/util/estraverse.js b/lib/util/estraverse.js
index d2e0d9a..57c4b70 100644
--- a/lib/util/estraverse.js
+++ b/lib/util/estraverse.js
@@ -10,8 +10,10 @@
 // Requirements
 //------------------------------------------------------------------------------

-var estraverse = require("estraverse"),
-    jsxKeys = require("estraverse-fb/keys");
+var path = require("path"),
+    estraverse = require("estraverse"),
+    jsxKeys = require("estraverse-fb/keys"),
+    resolve = require("resolve").sync;

 //------------------------------------------------------------------------------
 // Helers
@@ -48,6 +50,12 @@ installKeys(jsxKeys);
 // Add Experimental node types.
 installKeys(experimentalKeys);

+// Patch for escope.
+var escopePath = resolve("escope", {basedir: __dirname});
+var esrecursePath = resolve("esrecurse", {basedir: path.dirname(escopePath)});
+var estraversePath = resolve("estraverse", {basedir: path.dirname(esrecursePath)});
+require(estraversePath).VisitorKeys = estraverse.VisitorKeys;
+
 //------------------------------------------------------------------------------
 // Public Interface
 //------------------------------------------------------------------------------
```

